def write(name, title, subtitle, pages):
    html = ['<!doctype html><html lang="th"><head><meta charset="utf-8"><title>'+escape(title)+'</title><style>'+STYLE+'</style></head><body>']
    html.append(f'<section class="page cover"><header>✦ PAIMON <span>{escape(subtitle)}</span></header><p class="badge">ฉบับอัปเดต · 15 พฤศจิกายน 2569</p><h1>{escape(title)}</h1><p class="lead">{escape(subtitle)}</p><div class="intro"><h2>วิธีใช้คู่มือ</h2><p>เลือกหัวข้อที่เกี่ยวข้อง แล้วตรวจสภาพแวดล้อมและสิทธิ์ก่อนดำเนินการ ภาพประกอบใช้ข้อมูลจำลองจากระบบทดสอบ</p></div><div class="tip">อ้างอิง source และขั้นตอนที่ตรวจเมื่อ 15 พฤศจิกายน 2569 สถานะบริการและหน้าจออาจเปลี่ยนได้</div><footer>PAIMON GUIDE · 1</footer></section>')
    html.append('<section class="page"><header>✦ PAIMON <span>สารบัญ</span></header><h1>เลือกเรื่องที่ต้องการ</h1><ol>'+''.join(f'<li>{escape(title)} · {i+3}</li>' for i,(title,*_) in enumerate(pages))+'</ol><footer>สารบัญ · 2</footer></section>')
    for i,(heading, subheading, items, image) in enumerate(pages):
        figure = f'<div class="figure"><img src="screenshots/{image}" alt="ภาพหน้าจอระบบทดสอบ"></div>' if image else ''
        html.append(f'<section class="page"><header>✦ PAIMON <span>{escape(subtitle)}</span></header><h1>{escape(heading)}</h1><p class="lead">{escape(subheading)}</p>{figure}<ol>'+''.join(f'<li>{escape(item)}</li>' for item in items)+f'</ol><footer>{escape(subtitle)} · {i+3}</footer></section>')
    html.append('</body></html>')
    (OUT/name).write_text(''.join(html),encoding='utf-8')

write('paimon-operator-manual.html','คู่มือผู้ดูแลระบบและการปฏิบัติงาน','ผู้ดูแลแพลตฟอร์ม',OPERATIONS)
write('paimon-developer-manual.html','คู่มือนักพัฒนา Paimon','นักพัฒนาและผู้ดูแลโค้ด',DEVELOPER)
